-- Warranty Module Phase 3. Apply after V20260717_04. Test environment only.
ALTER TABLE warranty_claims ADD COLUMN IF NOT EXISTS bill_document_override_reason VARCHAR(1000);ALTER TABLE warranty_claims ADD COLUMN IF NOT EXISTS bill_document_overridden_at TIMESTAMP;ALTER TABLE warranty_claims ADD COLUMN IF NOT EXISTS bill_document_overridden_by_employee_id VARCHAR(80);
CREATE TABLE IF NOT EXISTS warranty_attachments(id BIGSERIAL PRIMARY KEY,warranty_claim_id BIGINT NOT NULL REFERENCES warranty_claims(id),warranty_replacement_id BIGINT REFERENCES warranty_replacements(id),category VARCHAR(60) NOT NULL,original_filename VARCHAR(255) NOT NULL,display_filename VARCHAR(255) NOT NULL,storage_provider VARCHAR(30) NOT NULL,storage_key VARCHAR(180) NOT NULL UNIQUE,detected_mime_type VARCHAR(80) NOT NULL,size_bytes BIGINT NOT NULL,checksum VARCHAR(64) NOT NULL,image_width INTEGER,image_height INTEGER,active BOOLEAN NOT NULL DEFAULT TRUE,superseded_by_attachment_id BIGINT REFERENCES warranty_attachments(id),uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,uploaded_by_employee_id VARCHAR(80) NOT NULL,uploaded_by_employee_name VARCHAR(120),deactivated_at TIMESTAMP,deactivated_by_employee_id VARCHAR(80),deactivation_reason VARCHAR(1000),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_warranty_attachment_category CHECK(category IN('BILL_IMAGE','WARRANTY_CARD_IMAGE','PRODUCT_IMAGE','PRODUCT_SERIAL_NUMBER_IMAGE','MANUFACTURER_SERVICE_SLIP','OTHER_WARRANTY_DOCUMENT','REPLACEMENT_PROOF','REPLACEMENT_PRODUCT_IMAGE','REPLACEMENT_SERIAL_NUMBER_IMAGE','REPLACEMENT_WARRANTY_CARD_IMAGE','OTHER_REPLACEMENT_DOCUMENT')),CONSTRAINT ck_warranty_attachment_size CHECK(size_bytes>0),CONSTRAINT ck_warranty_attachment_mime CHECK(detected_mime_type IN('image/jpeg','image/png','image/webp','application/pdf')),CONSTRAINT ck_warranty_attachment_deactivation CHECK((active=true AND deactivated_at IS NULL) OR active=false));
CREATE INDEX IF NOT EXISTS idx_warranty_attachments_claim ON warranty_attachments(warranty_claim_id,uploaded_at DESC);CREATE INDEX IF NOT EXISTS idx_warranty_attachments_replacement ON warranty_attachments(warranty_replacement_id,uploaded_at DESC);CREATE INDEX IF NOT EXISTS idx_warranty_attachments_category ON warranty_attachments(category,active);CREATE INDEX IF NOT EXISTS idx_warranty_attachments_checksum ON warranty_attachments(checksum);CREATE INDEX IF NOT EXISTS idx_warranty_attachments_cleanup ON warranty_attachments(deactivated_at) WHERE active=false;
CREATE UNIQUE INDEX IF NOT EXISTS uk_warranty_attachment_single_claim ON warranty_attachments(warranty_claim_id,category) WHERE active=true AND warranty_replacement_id IS NULL AND category IN('BILL_IMAGE','WARRANTY_CARD_IMAGE','PRODUCT_SERIAL_NUMBER_IMAGE','MANUFACTURER_SERVICE_SLIP');
CREATE UNIQUE INDEX IF NOT EXISTS uk_warranty_attachment_single_replacement ON warranty_attachments(warranty_replacement_id,category) WHERE active=true AND warranty_replacement_id IS NOT NULL AND category IN('REPLACEMENT_PROOF','REPLACEMENT_SERIAL_NUMBER_IMAGE','REPLACEMENT_WARRANTY_CARD_IMAGE');
ALTER TABLE warranty_claim_events DROP CONSTRAINT IF EXISTS ck_warranty_claim_events_type;
ALTER TABLE warranty_claim_events ADD CONSTRAINT ck_warranty_claim_events_type CHECK(event_type IN('WARRANTY_CLAIM_CREATED','WARRANTY_DETAILS_UPDATED','WARRANTY_OWNER_CHANGED','WARRANTY_STATE_CHANGED','WARRANTY_CLAIM_CLOSED','WARRANTY_COMPLAINT_REGISTRATION_PENDING','WARRANTY_COMPLAINT_REGISTERED','WARRANTY_VISIT_SCHEDULED','WARRANTY_EXPECTED_VISIT_UPDATED','WARRANTY_VISIT_RECORDED','WARRANTY_FOLLOW_UP_SCHEDULED','WARRANTY_FOLLOW_UP_UPDATED','WARRANTY_FOLLOW_UP_CLEARED','WARRANTY_MANUFACTURER_REPAIR_COMPLETED','WARRANTY_REJECTED','WARRANTY_REJECTION_DECISION_RECORDED','WARRANTY_CUSTOMER_DID_NOT_PROCEED','WARRANTY_REPLACEMENT_APPROVED','WARRANTY_MOVED_TO_READY_DELIVERY','WARRANTY_CONTINUED_AS_PAID_REPAIR','WARRANTY_REPLACEMENT_RECEIVED','WARRANTY_REPLACEMENT_DETAILS_UPDATED','WARRANTY_REPLACEMENT_SUPERSEDED','WARRANTY_REPLACEMENT_READY_FOR_DELIVERY','WARRANTY_REPLACEMENT_GIVEN_TO_CUSTOMER','WARRANTY_REPLACEMENT_CLAIM_CLOSED','WARRANTY_ATTACHMENT_UPLOADED','WARRANTY_ATTACHMENT_SUPERSEDED','WARRANTY_ATTACHMENT_DEACTIVATED','WARRANTY_DOCUMENT_REQUIREMENT_OVERRIDDEN'));
